# INT-53 backend_waiting_for_lock with a waiter on PostgreSQL and on markdown; the recipe utils holds the rest. The model is the clock
# fixture contracts/fixtures/clock.dbs, generated by orm-gen. Each case runs on a case database of its own; MySQL and
# PostgreSQL need ORM_TEST_MYSQL_DSN and ORM_TEST_POSTGRES_DSN, and a missing variable fails the case.
# Usage: packages/python/.venv/bin/python -m unittest packages.python.tests.test_was_inserted
import subprocess
import sys
import tempfile
import time
import unittest
from pathlib import Path

from . import testcase
from .case_database import case_database
from .test_sqlite import generate_document

from polyspec.orm.errors import OrmError

ROOT = Path(__file__).resolve().parents[3]
CLOCK = ROOT / "contracts" / "fixtures" / "clock.dbs"
CHILD = Path(__file__).resolve().parent / "was_inserted_child.py"


class WasInsertedTest(unittest.TestCase):
    deadline = testcase.DATABASE

    @classmethod
    def setUpClass(cls):
        cls.tmp = tempfile.TemporaryDirectory(prefix="orm-was-inserted-")
        cls.addClassCleanup(cls.tmp.cleanup)
        cls.models = generate_document(str(Path(cls.tmp.name) / "gen"), CLOCK)

    def run_case(self, dialect: str, body) -> None:
        with case_database(dialect, self.tmp.name, "was_inserted") as dsn:
            db = self.models.connect(dsn)
            try:
                db.utils().schema().install(self.models.SCHEMA)
                body(db, dsn)
            finally:
                db.close()

    def code(self, call) -> str:
        with self.assertRaises(OrmError) as caught:
            call()
        return caught.exception.code

    # Requirements: INT-53.
    def test_postgres_reports_a_backend_waiting_for_lock(self):
        def body(db, dsn):
            utils = db.utils()
            held = []

            def hold_insert():
                held.append(
                    self.models.ClockEvent()
                    .connect(db)
                    .set_label("held")
                    .create()
                    .get_seq()
                )

            db.transaction(hold_insert, {"retry": 0})

            def parent():
                self.models.ClockEvent().connect(db).set_seq(held[0]).set_label(
                    "parent"
                ).update()
                child = subprocess.Popen(
                    [sys.executable, str(CHILD), dsn, str(held[0])],
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True,
                )
                waiting = False
                deadline = time.monotonic() + 10
                while not waiting and time.monotonic() < deadline:
                    waiting = utils.backend_waiting_for_lock()
                    time.sleep(0.02)
                self.assertTrue(
                    waiting,
                    "the child backend waits for the row lock the transaction holds",
                )
                return child

            child = db.transaction(parent, {"retry": 0})
            out, err = child.communicate(timeout=60)
            self.assertEqual(child.returncode, 0, f"the waiting child failed: {err}")
            self.assertEqual(out, "done\n")

        self.run_case("postgres", body)


if __name__ == "__main__":
    testcase.main()
